package dev.veltraph.client.scheduling;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SourceRestRuntimeTest {
    static SourceRestRuntime.Observation facts(boolean disconnected,boolean arrival,boolean ready,long time){return new SourceRestRuntime.Observation(true,disconnected,arrival,ready,time);}
    static SourceRestRuntime disconnected(){var runtime=new SourceRestRuntime();runtime.start(0,60_000,20,45_000);for(int i=0;i<21;i++)assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(false,false,false,i)));assertEquals(SourceRestRuntime.Action.DISCONNECT,runtime.tick(facts(false,false,false,21)));return runtime;}
    @Test void sourceDelayIsChosenPlusTwoUpdatesAndDeadlineStartsBeforeDisconnect(){var runtime=disconnected();assertEquals(60_000,runtime.restEndsMillis());assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(true,false,false,60_000)));assertEquals(SourceRestRuntime.Action.REJOIN,runtime.tick(facts(true,false,false,60_001)));assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(true,false,false,60_002)));}
    @Test void nativeArrivalAndFreshReadinessAreSeparateAndRestartOnce(){var runtime=disconnected();runtime.tick(facts(true,false,false,60_001));assertEquals(SourceRestRuntime.Action.VERIFY_ARRIVAL,runtime.tick(facts(false,true,false,60_002)));assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(false,true,false,60_003)));assertEquals(SourceRestRuntime.Action.RESTART,runtime.tick(facts(false,true,true,60_004)));assertEquals(SourceRestRuntime.State.VERIFYING_ARRIVAL,runtime.state());assertTrue(runtime.restartPending());assertTrue(runtime.withinDeadline(60_004));assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(false,true,true,60_005)));assertTrue(runtime.commitRestart(facts(false,true,true,60_005)));assertEquals(SourceRestRuntime.State.COMPLETE,runtime.state());assertFalse(runtime.commitRestart(facts(false,true,true,60_006)));assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(false,true,true,60_007)));}
    static SourceRestRuntime pending(){var runtime=disconnected();runtime.tick(facts(true,false,false,60_001));runtime.tick(facts(false,true,false,60_002));assertEquals(SourceRestRuntime.Action.RESTART,runtime.tick(facts(false,true,true,60_003)));return runtime;}
    @Test void completeIsDeferredUntilTheExactResumeCallbackSucceeds(){var runtime=pending();var calls=new int[2];var handoff=new ScheduledResumeHandoff();assertTrue(handoff.complete(()->{calls[0]++;assertEquals(SourceRestRuntime.State.VERIFYING_ARRIVAL,runtime.state());assertTrue(runtime.restartPending());assertTrue(runtime.withinDeadline(60_004));return true;},()->calls[1]++,()->{},()->runtime.cancel("failed resume")));assertTrue(runtime.commitRestart(facts(false,true,true,60_004)));assertArrayEquals(new int[]{1,1},calls);assertFalse(handoff.complete(()->{calls[0]++;return true;},()->calls[1]++,()->{},()->{}));assertFalse(runtime.commitRestart(facts(false,true,true,60_005)));assertArrayEquals(new int[]{1,1},calls);}
    @Test void rejectedThrowingOrCancelledResumeNeverCompletesOrRetries(){for(int failure=0;failure<3;failure++){var runtime=pending();int mode=failure;var calls=new int[1];var handoff=new ScheduledResumeHandoff();assertFalse(handoff.complete(()->{calls[0]++;if(mode==1)throw new IllegalStateException("resume failed");if(mode==2)runtime.cancel("manual stop in callback");return false;},()->fail("Rejected resume replayed movement"),()->{},()->runtime.cancel("failed resume")));assertEquals(1,calls[0]);assertEquals(SourceRestRuntime.State.CANCELLED,runtime.state());assertFalse(runtime.commitRestart(facts(false,true,true,60_004)));assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(false,true,true,60_005)));}}
    @Test void commitRequiresPendingReadyMatchedTicketWithinOriginalDeadline(){assertFalse(disconnected().commitRestart(facts(false,true,true,60_004)));for(var invalid:new SourceRestRuntime.Observation[]{new SourceRestRuntime.Observation(false,false,true,true,60_004),facts(true,true,true,60_004),facts(false,false,true,60_004),facts(false,true,false,60_004),facts(false,true,true,105_001),facts(false,true,true,60_002)}){var runtime=pending();assertFalse(runtime.commitRestart(invalid));assertEquals(SourceRestRuntime.State.CANCELLED,runtime.state());assertFalse(runtime.restartPending());assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(false,true,true,105_002)));}}
    @Test void unexpectedWorldAndInvalidTicketCancelWithoutRestartOrAnotherRejoin(){var runtime=disconnected();assertEquals(SourceRestRuntime.Action.CANCEL,runtime.tick(facts(false,true,true,100)));assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(true,false,false,100_000)));runtime=disconnected();assertEquals(SourceRestRuntime.Action.CANCEL,runtime.tick(new SourceRestRuntime.Observation(false,true,false,false,100)));}
    @Test void timeoutAndBackwardClockFailClosed(){var runtime=disconnected();runtime.tick(facts(true,false,false,60_001));assertEquals(SourceRestRuntime.Action.CANCEL,runtime.tick(facts(true,false,false,105_001)));assertEquals(SourceRestRuntime.State.FAILED,runtime.state());runtime=disconnected();assertEquals(SourceRestRuntime.Action.CANCEL,runtime.tick(facts(true,false,false,0)));}
    @Test void manualCancelAndMalformedScheduleNeverIssueTransport(){var runtime=disconnected();runtime.cancel("manual stop");assertEquals(SourceRestRuntime.Action.NONE,runtime.tick(facts(true,false,false,90_000)));assertThrows(IllegalArgumentException.class,()->runtime.start(0,59_999,20,1));assertThrows(IllegalArgumentException.class,()->runtime.start(0,60_000,120,1));}
}
